const express = require('express');
const Redis = require('ioredis');
const { verifyJwt } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const redisSubscriber = new Redis(process.env.REDIS_URL);

router.get('/api/transfers/:transferId/poll-status', verifyJwt, async (req, res) => {
  const { transferId } = req.params;

  const transfer = await db.query(
    'SELECT id FROM wire_transfers WHERE id = $1 AND (sender_user_id = $2 OR recipient_user_id = $2)',
    [transferId, req.user.id]
  );
  if (!transfer.rows.length) {
    return res.status(403).json({ error: 'Access denied: unauthorized transfer polling' });
  }

  const channel = `transfer:${transferId}:status`;
  const timeoutId = setTimeout(() => {
    redisSubscriber.unsubscribe(channel);
    res.json({ status: 'TIMEOUT', message: 'No status change' });
  }, 25000);

  redisSubscriber.subscribe(channel, () => {
    redisSubscriber.once('message', (chan, message) => {
      if (chan === channel) {
        clearTimeout(timeoutId);
        redisSubscriber.unsubscribe(channel);
        res.json({ status: 'UPDATED', transferData: JSON.parse(message) });
      }
    });
  });
});
